import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.CGSzHL4z.js";const u=JSON.parse('{"title":"Keyboard shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"reference/shortcuts.md","filePath":"reference/shortcuts.md","lastUpdated":1791952279000}'),i={name:"reference/shortcuts.md"};function s(c,t,n,a,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>Every default key. Change them in Settings &gt; Shortcuts.</p><ul><li>Defaults avoid the keys Studio keeps for itself, which never reach a plugin: <strong>Delete</strong> (it does arrive in the Timeline because the Timeline sets Studio&#39;s selection aside), <strong>Ctrl+C, Ctrl+V, Ctrl+X, Ctrl+D</strong>, <strong>Shift+X</strong>, <strong>O</strong>, <strong><code>,</code></strong> and <strong><code>.</code></strong> (Studio&#39;s camera keys), and <strong>any key you or another plugin bound in Studio&#39;s File &gt; Customize Shortcuts</strong> (those are global and a plugin cannot read them). That is why paste and duplicate are <code>Shift+V</code> / <code>Shift+D</code>, the frame steps are the arrows, and loop in/out are <code>Shift+I</code> / <code>Shift+O</code>. Copy is <code>Shift+C</code>.</li><li><code>Ctrl+Z</code> and <code>Ctrl+Y</code> are Studio&#39;s undo and redo; every AcesMotion edit, poses included, is a step. Edit &gt; Undo names the step.</li><li>Every shortcut is also a Studio plugin action named &quot;AcesMotion: {name}&quot; (no default key there), so you can bind it in Studio&#39;s own shortcut editor. Plugin actions fire on press only; hold keys (Space, P, I, Tab, J) fire their release when the plugin action is used.</li><li><strong>Rebinding inside AcesMotion</strong>: every shortcut, in Settings &gt; Shortcuts (right click a row to clear it or reset it). The hold keys also have their field on their own page: Temporary pivot key, Pin key (<code>Shift</code> plus it clears pins), Context IK key and Look through key (Posing page), Timing key (Trajectory page). A key another shortcut already uses in the same place is refused (&quot;X is taken by {name}&quot;), and so are Studio&#39;s own Ctrl+C, V, X, D, Z and Y. Reset this group puts them back. Commands can also be bound in Studio&#39;s shortcut editor (File &gt; Customize Shortcuts) as global keys.</li><li>Keys are ignored while a text box has focus.</li><li><strong>Scope</strong>: <em>Timeline</em> works while the Timeline has focus (and <strong>hover</strong> keys also while the pointer is over it); <em>Viewport</em> works while no AcesMotion window has focus (the 3D view); <em>Any</em> works in either; <em>Inspector</em> is the Inspector window.</li></ul><table tabindex="0"><thead><tr><th>Action</th><th>Default key</th><th>Scope</th><th>Notes</th></tr></thead><tbody><tr><td>Play or pause</td><td><code>Space</code></td><td>Timeline (hover)</td><td>Tap plays or pauses; hold and drag pans.</td></tr><tr><td>Key selected</td><td><code>K</code></td><td>Timeline</td><td>Keys the selected rows at the playhead; with none selected the picked joints/posed tracks, else the selected actors.</td></tr><tr><td>Key whole actor</td><td><code>Shift+K</code></td><td>Timeline (hover)</td><td>Every joint of the selected rigs, keyed or not (not their root); the root of any other actor.</td></tr><tr><td>Previous frame / Next frame</td><td><code>Left</code> / <code>Right</code></td><td>Timeline</td><td>Stops playback.</td></tr><tr><td>Previous key / Next key</td><td><code>Up</code> / <code>Down</code></td><td>Timeline</td><td>Of the whole scene.</td></tr><tr><td>Go to start / Go to end</td><td><code>Home</code> / <code>End</code></td><td>Timeline (hover)</td><td>Of the loop region when there is one.</td></tr><tr><td>Loop in / Loop out</td><td><code>Shift+I</code> / <code>Shift+O</code></td><td>Timeline (hover)</td><td>At the playhead.</td></tr><tr><td>Frame selected</td><td><code>F</code></td><td>Timeline</td><td>Selected keys, else loop region, else all; in the curve graph also the values.</td></tr><tr><td>Frame all</td><td><code>A</code></td><td>Timeline</td><td>In the curve graph also the values.</td></tr><tr><td>Ease selected keys</td><td><code>E</code></td><td>Timeline</td><td>Opens or closes the Ease window.</td></tr><tr><td>Switch dope sheet and curves</td><td><code>Tab</code></td><td>Timeline</td><td>Dope sheet &gt; Ease view &gt; Channels view &gt; Dope sheet; in Split swaps the lower part.</td></tr><tr><td>Zoom in / Zoom out</td><td><code>=</code> / <code>-</code></td><td>Timeline (hover)</td><td>Around the pointer (or the playhead).</td></tr><tr><td>Copy keys</td><td><code>Shift+C</code></td><td>Timeline (hover)</td><td>Keys, blocks, Camera switch keys and attach keys.</td></tr><tr><td>Paste keys</td><td><code>Shift+V</code></td><td>Timeline (hover)</td><td>At the playhead, onto what you selected last (a block&#39;s lane, a row, a key&#39;s row or an actor). Blocks, switch keys and attach keys too.</td></tr><tr><td>Paste keys mirrored</td><td><code>Shift+N</code></td><td>Timeline (hover)</td><td></td></tr><tr><td>Duplicate keys</td><td><code>Shift+D</code></td><td>Timeline (hover)</td><td>With blocks selected, duplicates the blocks instead; keys and blocks selected together are duplicated together.</td></tr><tr><td>Delete keys</td><td><code>Del</code></td><td>Timeline (hover)</td><td>With blocks selected, deletes the blocks instead; keys and blocks selected together are deleted together. With no keys or blocks selected: deletes the selected marker, else removes the selected rows&#39; tracks (property, object, joint and root rows as Remove from timeline, action tracks as Remove action track), one undo step; actor rows stay (a note says to use their menu). Keys on a locked track or actor are left, stay selected, and the status bar names the lock (&quot;root is locked: 12 keys stayed selected. Unlock it to delete them.&quot;).</td></tr><tr><td>Delete keys (Backspace)</td><td><code>Backspace</code></td><td>Timeline (hover)</td><td>The same as Del (a Mac laptop has no Del key); its own shortcut, so it can be rebound or cleared.</td></tr><tr><td>Nudge keys left / right</td><td><code>[</code> / <code>]</code></td><td>Timeline (hover)</td><td>One frame.</td></tr><tr><td>Nudge keys 10 frames left / right</td><td><code>Shift+[</code> / <code>Shift+]</code></td><td>Timeline (hover)</td><td></td></tr><tr><td>Nudge keys left / right (arrow)</td><td><code>Shift+Left</code> / <code>Shift+Right</code></td><td>Timeline (focused)</td><td>One frame, like <code>[</code> <code>]</code></td></tr><tr><td>Clear key selection</td><td><code>Esc</code></td><td>Timeline (hover)</td><td>Clears the selected keys, blocks, switch keys, attach keys, marker and rows.</td></tr><tr><td>Rename action track</td><td><code>F2</code></td><td>Timeline</td><td>With one action track header selected: edits its name in place.</td></tr><tr><td>Select all keys</td><td>none</td><td>Timeline</td><td>Also in the Edit menu.</td></tr><tr><td>Toggle auto-key</td><td><code>Ctrl+Shift+K</code></td><td>Any</td><td></td></tr><tr><td>Toggle onion skin</td><td><code>Ctrl+Shift+O</code></td><td>Any</td><td></td></tr><tr><td>Switch gizmo space</td><td><code>R</code></td><td>Any</td><td>Local &gt; Parent &gt; World.</td></tr><tr><td>Switch gizmo handles</td><td><code>T</code></td><td>Any</td><td>Move &amp; rotate and Resize; with separate handles Move, Rotate, Resize.</td></tr><tr><td>Pin parts</td><td><code>P</code></td><td>Any</td><td>Tap to pin or unpin the picked parts; hold and click a part. Holds through a click into the viewport.</td></tr><tr><td>Clear all pins</td><td><code>Shift+P</code></td><td>Any</td><td>Follows the pin key if rebound.</td></tr><tr><td>Lock picked</td><td><code>Shift+L</code></td><td>Any</td><td>A Lock on each picked part, from the playhead to its next key (or a second).</td></tr><tr><td>Mirror posing</td><td><code>Shift+M</code></td><td>Any</td><td></td></tr><tr><td>Trail timing (hold)</td><td><code>J</code></td><td>Any</td><td>Also read by polling while the viewport has focus, so it can work there; if another binding owns <code>J</code> on your machine, rebind it (Settings &gt; Trajectory &gt; Timing key).</td></tr><tr><td>Copy pose</td><td><code>Shift+C</code></td><td>Viewport</td><td></td></tr><tr><td>Paste pose</td><td><code>Shift+V</code></td><td>Viewport</td><td></td></tr><tr><td>Paste pose mirrored</td><td><code>Shift+N</code></td><td>Viewport</td><td></td></tr><tr><td>Flip pose</td><td><code>Shift+F</code></td><td>Viewport</td><td></td></tr><tr><td>Reset to rest</td><td><code>Shift+R</code></td><td>Viewport</td><td></td></tr><tr><td>Attach to</td><td><code>Shift+G</code></td><td>Viewport, Timeline</td><td>The picked part or actor follows what you click next, from the playhead.</td></tr><tr><td>Detach</td><td><code>Shift+Alt+G</code></td><td>Viewport, Timeline</td><td>At the playhead; it stays where it was.</td></tr><tr><td>Back to rig</td><td><code>Shift+Alt+A</code></td><td>Viewport, Timeline</td><td>Rig joints only: snaps back into its place on the rig (Blend on the key eases it).</td></tr><tr><td>Back to rig where it is</td><td>none</td><td>Viewport, Timeline</td><td>Rig joints only: rejoins its rig keeping where it is now. Bind it in Settings &gt; Shortcuts.</td></tr><tr><td>Select mirror</td><td>none</td><td>Viewport</td><td>Also in the Pose menu.</td></tr><tr><td>Pick the joint above / below</td><td><code>[</code> / <code>]</code></td><td>Viewport</td><td></td></tr><tr><td>Temporary pivot (hold)</td><td><code>Tab</code></td><td>Viewport</td><td></td></tr><tr><td>Context IK (hold)</td><td><code>I</code></td><td>Viewport</td><td>Flips FK/IK for a drag.</td></tr><tr><td>Shorter / Longer IK chain</td><td><code>Ctrl+[</code> / <code>Ctrl+]</code></td><td>Viewport</td><td></td></tr><tr><td>Let go of the picked joints</td><td><code>Esc</code></td><td>Viewport</td><td>Cancels a gizmo drag first, then drops a path point pick, then the pick.</td></tr><tr><td>Look through camera</td><td><code>Q</code></td><td>Viewport and Timeline</td><td>Toggles look-through (always turns it off, also while looking away). Ignored while a mouse button is held (Studio flies down with right mouse + <code>Q</code>) and with <code>Ctrl</code>, <code>Alt</code> or <code>Meta</code> held. While held, the view stays still (Studio would fly it down).</td></tr><tr><td>Align camera to view</td><td><code>Shift+Q</code></td><td>Viewport and Timeline</td><td>Moves the selected camera actor (else the live one) to your view and keys it at the playhead. Ignored while a mouse button is held; when it can&#39;t run (the view is locked on the camera, no camera) the reason shows in the status bar.</td></tr><tr><td>Pilot camera</td><td><code>Ctrl+Shift+Q</code></td><td>Viewport and Timeline</td><td>Turns Pilot camera on (looking through first if needed) or off. When it can&#39;t, the reason shows in the status bar. Ignored while a mouse button is held.</td></tr><tr><td>Focus camera on the pointer</td><td><code>F</code></td><td>Viewport</td><td>With a camera picked (Move or Rotate gizmo) or selected in the Timeline or Hub, or the piloted camera, turns it to look at what&#39;s under the pointer, keeping position and roll (Reset roll when focusing levels it). Keyed with Auto-key, one undo step. Does nothing with no camera picked. Ignored while a mouse button is held.</td></tr><tr><td>Focus camera and level it</td><td><code>Ctrl+F</code></td><td>Viewport</td><td>As Focus camera on the pointer, and levels the roll to 0. While looking through, both work only with Pilot camera on.</td></tr><tr><td>Key property</td><td><code>K</code></td><td>Inspector (hover)</td><td>Keys the property row under the pointer.</td></tr><tr><td>Copy property value</td><td><code>Shift+C</code></td><td>Inspector (hover)</td><td>Copies the value of the property row under the pointer, else the picked row.</td></tr><tr><td>Paste property value</td><td><code>Shift+V</code></td><td>Inspector (hover)</td><td>Pastes onto the row under the pointer, else onto every picked row.</td></tr><tr><td>Open settings</td><td>none</td><td>Any</td><td></td></tr><tr><td>Reset window layout</td><td>none</td><td>Any</td><td></td></tr><tr><td>Toggle effect preview</td><td>none</td><td>Any</td><td>Same as View &gt; Effect preview.</td></tr><tr><td>Apply pose slot 1 ... 9</td><td><code>Alt+1</code> ... <code>Alt+9</code></td><td>Viewport, Timeline</td><td>With <code>Shift</code> mirrored, with <code>Ctrl</code> to the whole actor.</td></tr><tr><td>Quick pose</td><td><code>Ctrl+Alt+P</code></td><td>Viewport, Timeline</td><td>The quick pose picker at the pointer.</td></tr><tr><td>Save version</td><td><code>Alt+Shift+S</code></td><td>Anywhere in AcesMotion</td><td>A version of the open scene with an automatic name (Scene &gt; Save).</td></tr><tr><td>Apply pose</td><td><code>Enter</code></td><td>Library (Poses tab)</td><td>The pose under the pointer; with <code>Shift</code> mirrored, with <code>Ctrl</code> whole actor.</td></tr><tr><td>Rename pose</td><td><code>F2</code></td><td>Library (Poses tab)</td><td>The pose under the pointer.</td></tr><tr><td>Duplicate pose</td><td><code>Shift+D</code></td><td>Library (Poses tab)</td><td>The pose under the pointer.</td></tr><tr><td>Delete pose</td><td><code>Del</code> / <code>Backspace</code></td><td>Library (Poses tab)</td><td>The pose under the pointer; Undo in the status line.</td></tr></tbody></table><p>Fixed keys inside windows and menus (not rebindable):</p><ul><li><strong>Menus</strong>: <code>Esc</code> closes; <code>Up</code> / <code>Down</code> move (skipping greyed items); <code>Return</code> / <code>Enter</code> run the highlighted item or open its submenu; <code>Right</code> opens a submenu; <code>Left</code> closes a submenu; any other key closes the menu. With the mouse, a submenu opens on hover and stays open while you move into it, even across other items on the way (it closes a moment after you settle on another item). In a narrow window a submenu that can&#39;t fit beside its menu opens just below its item. Tooltips of things under an open menu stay hidden. Menu items whose name doesn&#39;t say what they do show a tooltip card while hovered (about 250 across the Timeline, viewport, Hub and Inspector menus).</li><li><strong>On a Mac, <code>Cmd</code> works wherever these pages say <code>Ctrl</code></strong> (snapping flips, multi-select, shortcuts).</li><li><strong>Text fields</strong>: <code>Enter</code> keeps, <code>Esc</code> cancels (Inspector text, asset id, attribute name, rename boxes, search boxes clear on <code>Esc</code>).</li><li><strong>Number fields (scrub)</strong>: <code>Shift</code> finer, <code>Ctrl</code> whole numbers, <code>Esc</code> puts the value back.</li><li><strong>Editor windows</strong>: <code>Esc</code> during a drag in the window cancels just that drag. <code>Enter</code> = OK (unless a field is being typed in), <code>Esc</code> = Cancel, <code>Del</code> / <code>Backspace</code> removes the selected point or stop, <code>Ctrl+Z</code> / <code>Ctrl+Y</code> step through the window&#39;s changes, <code>F2</code> / <code>Del</code> over a saved swatch rename / delete it. The Presets menu takes <code>Esc</code>, <code>Up</code>, <code>Down</code>, <code>Home</code>, <code>End</code>, <code>Enter</code>.</li><li><strong>Ease canvas</strong>: <code>Shift</code> snaps a dragged handle to 0.05, <code>Alt</code> ignores snapping.</li><li><strong>Sequence editor</strong>: <code>Shift</code> snaps a dragged point&#39;s time to 0.05.</li><li><strong>Instance picker</strong>: <code>Enter</code> picks the first match, <code>Esc</code> closes.</li></ul>',6)])])}const m=e(i,[["render",s]]);export{u as __pageData,m as default};
